mapper.sql:
WHERE lp.status = 'ACTIVE'
  AND d.status IN ('ON_SALE', 'SOLD_OUT')
  AND d.is_join_lottery = 1
  AND m.apply_status = 'APPROVED'
  AND m.status = 'OPEN'
  AND s.status = 'OPEN'
  AND c.status = 'OPEN'

    AND lp.canteen_id = #{canteenId}


    AND lp.price >= #{minPrice}


    AND lp.price <= #{maxPrice}


    AND lp.score >= #{minScore}


    AND EXISTS (
        SELECT 1
        FROM dish_tag dt
        WHERE dt.dish_id = d.id
          AND dt.tag_id IN

              #{tagId}

    )


    AND EXISTS (
        SELECT 1
        FROM favorite f
        WHERE f.user_id = #{favoriteUserId}
          AND f.target_type = 'DISH'
          AND f.target_id = d.id
    )

mapper.select:
SELECT dt.dish_id AS sourceId, t.name AS tagName FROM dish_tag dt INNER JOIN tag t ON t.id = dt.tag_id WHERE dt.dish_id IN
#{dishId}
AND t.status = 'ACTIVE' ORDER BY t.sort_order ASC, t.id ASC

SELECT di.dish_id AS sourceId, di.image_url AS imageUrl FROM dish_image di WHERE di.dish_id IN
#{dishId}
ORDER BY di.is_cover DESC, di.sort_order ASC, di.id ASC
